def add_program_forms(apps, schema_editor):
    Program = apps.get_model("academics", "Program")
    Document = apps.get_model("academics", "ProgramDocument")
    alias = schema_editor.connection.alias
    previous_steps = import_module("apps.academics.migrations.0017_thesis_procedures").COMMON_STEPS
    bsca = Program.objects.using(alias).filter(code="BSCA").first()
    if bsca:
        lines = (bsca.thesis_information or "").splitlines()
        updated = [line.replace("the graduate coordinator", "your thesis adviser or the department") if line in previous_steps else line for line in lines]
        if updated != lines:
            Program.objects.using(alias).filter(pk=bsca.pk).update(thesis_information="\n".join(updated))
    for index, item in enumerate(FORMS):
        program = Program.objects.using(alias).filter(code=item["code"]).first()
        if not program:
            continue
        Document.objects.using(alias).get_or_create(program_id=program.pk, url=item["url"], defaults={
            "title": item["title"], "form_group": item["form_group"], "note": item["note"],
            "document_type": "OTHER", "is_public": True, "sort_order": 100 + index,
        })


